"""Supplied image noise predictor. Students do not edit this file."""
from pathlib import Path
import torch
from torch import nn
import torch.nn.functional as F


class TinyNoisePredictor(nn.Module):
    def __init__(self, steps=64):
        super().__init__()
        self.steps = steps
        self.enc = nn.Sequential(nn.Conv2d(5, 16, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(16, 16, 3, padding=1), nn.SiLU())
        self.mid = nn.Sequential(nn.Conv2d(16, 32, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(32, 32, 3, padding=1), nn.SiLU())
        self.dec = nn.Sequential(nn.Conv2d(48, 16, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(16, 16, 3, padding=1), nn.SiLU(),
                                 nn.Conv2d(16, 1, 3, padding=1))

    def forward(self, x, t):
        phase = t.to(x.dtype) / (self.steps - 1)
        features = torch.stack([phase, phase.square(),
                                torch.sin(torch.pi * phase),
                                torch.cos(torch.pi * phase)], dim=1)
        features = features[:, :, None, None].expand(-1, -1, *x.shape[-2:])
        skip = self.enc(torch.cat([x, features], dim=1))
        low = self.mid(F.avg_pool2d(skip, 2))
        up = F.interpolate(low, size=x.shape[-2:], mode="nearest")
        return self.dec(torch.cat([skip, up], dim=1))


def load_model(path=None):
    path = Path(path) if path else Path(__file__).with_name("pa5_shapes.pt")
    payload = torch.load(path, map_location="cpu", weights_only=True)
    model = TinyNoisePredictor(steps=len(payload["betas"]))
    model.load_state_dict(payload["state_dict"])
    model.eval()
    return model, payload["betas"]
